program.compute:
options=read('/input/options')
ids=[x['id'] for x in options]
result=[]
for k in range(2,5):
 for group in combinations(ids,k):
  chosen=list(group)
  if valid(chosen):
   result=chosen
   break
 if result:
  break

program.effects:
if exists('/output/selection'):
 selected=read('/output/selection')
else:
 write('/output/selection',result)
 selected=read('/output/selection')
if receipt('report')=='success':
 pass
else:
 if receipt('report')=='unknown':
  status('report')
 if receipt('report')=='unattempted' or receipt('report')=='failure':
  send('report','team',selected)
if exists('/tmp/cache'):
 delete('/tmp/cache')

